 if(id==="multiball_jackpot"){vsxArcadeStart(this,id,8,{spawn:0});for(let i=0;i<5;i++){const a=i*Math.PI*2/5;const q=new Projectile({x:p.x,y:p.y,vx:Math.cos(a)*620,vy:Math.sin(a)*620,radius:9,damage:44*p.damageMultiplier,life:8,bounce:14,color:"#ff78e2",weapon:src,knockback:45});q.rampingBounce=true;this.projectiles.push(q)}return}
