 if(id==="around_the_world"){vsxArcadeStart(this,id,8,{snap:false});const stats={...new WeaponInstance("void_yoyo").getStats(),damage:34*p.damageMultiplier,range:270,size:15};this.effects.push(new VSXArcadeYoyo(src,stats,0,true),new VSXArcadeYoyo(src,stats,1,true));return}
 if(id==="rush_hour")return vsxArcadeStart(this,id,8,{lane:0,n:0});
 if(id==="last_train")return vsxArcadeStart(this,id,9,{train:0,n:0});
 if(id==="domino_day"){vsxArcadeStart(this,id,4.8);for(let i=0;i<24;i++){const a=i*.82,rr=70+i*10,x=p.x+Math.cos(a)*rr,y=p.y+Math.sin(a)*rr;this.effects.push(new PulseDelayEffect(i*.12,()=>this.effects.push(new WaveEffect(x,y,54,.34,30*p.damageMultiplier*(1+i*.018),55,src,i%2?"#e8ebf6":"#a7b1c8"))))}return}
 if(id==="jackpot_drop"){
  vsxArcadeStart(this,id,2.7);
  const ts=this.enemies.filter(e=>!e.dead&&!e.isCaptive).sort((a,b)=>(Number(b.isBoss)-Number(a.isBoss))||(Number(b.elite)-Number(a.elite))||b.hp-a.hp).slice(0,3);
  ts.forEach((e,i)=>{
    this.effects.push(new PulseDelayEffect(i*.55,()=>{
      if(e.dead)return;
      this.telegraphs.push(new VSX_Telegraph({
        x:e.x,y:e.y,r:95,life:.36,color:"#ffbd72",
        callback:()=>{
          this.explosion(e.x,e.y,100,110*p.damageMultiplier*(1+i*.28),"#ffbd72",150,src,false);
          this.texts.push(new FloatingText(e.x,e.y-44,"JACKPOT!","#ffd870",16));
        }
      }));
    }));
  });
  return;
 }
 if(id==="break_shot"){vsxArcadeStart(this,id,1.8);const ts=this.nearestList(p.x,p.y,900,14);let prev={x:p.x,y:p.y};ts.forEach((e,i)=>this.effects.push(new PulseDelayEffect(i*.07,()=>{if(e.dead)return;this.beams.push({x1:prev.x,y1:prev.y,x2:e.x,y2:e.y,life:.12,color:"#e9f8ff",width:7});this.damageEnemy(e,56*p.damageMultiplier*(1+i*.08),{source:src,canCrit:true,knockback:105,fromX:prev.x,fromY:prev.y});prev={x:e.x,y:e.y}})));return}
 if(id==="pipe_network")return vsxArcadeStart(this,id,9,{portal:0,shot:0});
 if(id==="false_awakening")return vsxArcadeStart(this,id,10,{dream:0});
 if(id==="hall_of_mirrors")return vsxArcadeStart(this,id,10,{mirror:0,reflect:0});
 if(id==="compile_all")return vsxArcadeStart(this,id,9,{compile:0});
